class Solution {
  public long minArraySum(int[] nums, int k) {
    long INF = Long.MAX_VALUE / 4;
    long[] best = new long[k];
    java.util.Arrays.fill(best, INF);
    best[0] = 0;
    long dp = 0;
    int mod = 0;
    for (int x : nums) {
      mod = (mod + x) % k;
      dp = Math.min(dp + x, best[mod]);
      best[mod] = Math.min(best[mod], dp);
    }
    return dp;
  }
}
